mapper.select:
SELECT * FROM ( SELECT inner_query.*, ROWNUM row_num FROM ( SELECT p.post_id, p.member_id, p.case_type, p.title, p.content, p.view_cnt, p.comment_cnt, p.like_cnt, p.status, p.created_at, p.updated_at, m.name FROM tb_post p JOIN tb_member m ON p.member_id = m.member_id WHERE p.status = 'ACTIVE' AND p.case_type != 'POLL'
ORDER BY p.view_cnt DESC, p.post_id DESC
ORDER BY p.comment_cnt DESC, p.post_id DESC
ORDER BY p.post_id DESC
) inner_query WHERE ROWNUM <= #{endRow} ) WHERE row_num >= #{startRow}

mapper.update:
UPDATE tb_post
SET status = #{status}, updated_at = SYSDATE
WHERE post_id = #{postId}

UPDATE tb_post
SET comment_cnt = comment_cnt + 1
WHERE post_id = #{postId}

mapper.select:
SELECT COUNT(*)
FROM tb_post_like
WHERE post_id = #{postId}
  AND member_id = #{memberId}

mapper.delete:
DELETE FROM tb_post_like
WHERE post_id = #{postId}
  AND member_id = #{memberId}

mapper.update:
UPDATE tb_post
SET like_cnt = like_cnt + 1
WHERE post_id = #{postId}

mapper.select:
SELECT * FROM ( SELECT inner_query.*, ROWNUM row_num FROM ( SELECT p.poll_id, p.post_id, p.member_id, p.title, p.description, p.disclaimer, p.end_date, p.status, p.created_at, m.name FROM tb_poll p JOIN tb_member m ON p.member_id = m.member_id WHERE p.status != 'DELETED'
ORDER BY p.end_date ASC, p.poll_id DESC
ORDER BY CASE WHEN p.status = 'OPEN' THEN 0 ELSE 1 END, p.poll_id DESC
ORDER BY p.poll_id DESC
) inner_query WHERE ROWNUM <= #{endRow} ) WHERE row_num >= #{startRow}

